const verificationId = $input.first().json.body.verification_id;

const data = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://ceogbuepvunwyavltcgu.supabase.co/rest/v1/verifications?id=eq.' + verificationId + '&select=*',
  headers: {
    'apikey': 'PEGAR_ANON_KEY',
    'Authorization': 'Bearer PEGAR_SERVICE_KEY'
  },
  json: true
});

if (!data || data.length === 0) {
  throw new Error('Verification not found');
}

return [{ json: data[0] }];

const openaiResponse = $input.first().json;
const v = $('Get Verification').item.json;

try {
  let content = openaiResponse.choices[0].message.content;

  // Si la respuesta es un refusal de OpenAI
  if (!content || content.trim().startsWith('Lo siento') || content.trim().startsWith('I cannot') || content.trim().startsWith('I\'m sorry')) {
    throw new Error('OpenAI refused to analyze: ' + content.substring(0, 100));
  }

  content = content.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  const parsed = JSON.parse(content);

  // === EXTRAER DATOS ===
  const extractedName = (parsed.extracted_data?.full_name || '').toLowerCase().trim();
  const operatorName = (v.first_name + ' ' + v.last_name).toLowerCase().trim();
  const nameMatch = extractedName.includes(operatorName) || operatorName.includes(extractedName);

  const extractedDni = (parsed.extracted_data?.dni_number || '').replace(/[^0-9]/g, '');
  const operatorDni = (v.dni || '').replace(/[^0-9]/g, '');
  const dniMatch = extractedDni === operatorDni;

  const cardLastFour = (v.card_last_four || '').replace(/[^0-9]/g, '');
  const extractedLastFour = (parsed.card_photo?.last_four_visible || '').replace(/[^0-9]/g, '');
  const cardMatch = cardLastFour && extractedLastFour ? cardLastFour === extractedLastFour : false;

  const overallScore = parsed.overall_score ?? 0;
  let recommendation = parsed.recommendation || 'low_risk';
  const indicators = Array.isArray(parsed.indicators) ? parsed.indicators : (Array.isArray(parsed.fraud_signals) ? parsed.fraud_signals : []);
  const isEditable = parsed.card_photo?.is_editable === true;

  // === REGLAS POST-PROCESO ===
  // 1. Si la tarjeta parece editada/digital → high_risk
  if (isEditable && recommendation !== 'high_risk') {
    recommendation = 'high_risk';
  }

  // 2. Si hay indicadores con severity high y confianza >= 70 → high_risk
  const highSeverityIndicators = indicators.filter(s => s.severity === 'high' && (s.confidence || 0) >= 70);
  if (highSeverityIndicators.length > 0 && recommendation !== 'high_risk') {
    recommendation = 'high_risk';
  }

  // 3. Si overall_score < 50 → high_risk
  if (overallScore < 50 && recommendation !== 'high_risk') {
    recommendation = 'high_risk';
  }

  // 4. Si overall_score < 70 y era low_risk → manual_review
  if (overallScore < 70 && recommendation === 'low_risk') {
    recommendation = 'manual_review';
  }

  // 5. Si algún dato no coincide → subir nivel de riesgo
  if (!nameMatch || !dniMatch) {
    if (recommendation === 'low_risk') recommendation = 'medium_risk';
  }

  return [{
    json: {
      verification_id: v.id,
      extracted_name: parsed.extracted_data?.full_name || '',
      extracted_dni: parsed.extracted_data?.dni_number || '',
      extracted_birth_date: parsed.extracted_data?.birth_date || '',
      dni_front_score: parsed.dni_front?.score || 0,
      dni_back_score: parsed.dni_back?.score || 0,
      dni_front_findings: parsed.dni_front?.findings || [],
      dni_back_findings: parsed.dni_back?.findings || [],
      card_photo_score: parsed.card_photo?.score || 0,
      card_photo_findings: parsed.card_photo?.findings || [],
      overall_score: overallScore,
      fraud_signals: indicators,
      data_match: {
        name_match: nameMatch,
        dni_match: dniMatch,
        card_match: cardMatch,
      },
      data_consistency: parsed.data_consistency || {},
      summary: parsed.summary || [],
      recommendation: recommendation,
      raw_response: openaiResponse,
      analyzed_at: new Date().toISOString(),
      analyzed_by: 'openai-gpt4o-forensic-v3'
    }
  }];
} catch (err) {
  // Si es refusal de OpenAI, devolver resultado con medium_risk
  const errorMsg = err.message || '';
  if (errorMsg.includes('refused') || errorMsg.includes('Lo siento')) {
    return [{
      json: {
        verification_id: v.id,
        extracted_name: '',
        extracted_dni: '',
        extracted_birth_date: '',
        dni_front_score: 0,
        dni_back_score: 0,
        dni_front_findings: ['El modelo de análisis no pudo procesar las imágenes'],
        dni_back_findings: [],
        card_photo_score: 0,
        card_photo_findings: [],
        overall_score: 0,
        fraud_signals: [{ signal: 'analysis_unavailable', severity: 'medium', confidence: 100, location: 'sistema', description: 'El modelo de análisis no pudo procesar las imágenes. Se requiere revisión manual.' }],
        data_match: { name_match: false, dni_match: false, card_match: false },
        data_consistency: {},
        summary: ['El análisis automático no pudo completarse. Se requiere revisión manual.'],
        recommendation: 'manual_review',
        raw_response: openaiResponse,
        analyzed_at: new Date().toISOString(),
        analyzed_by: 'openai-gpt4o-forensic-v3'
      }
    }];
  }
  throw new Error('Failed to parse OpenAI response: ' + err.message);
}
